package org.ssssssss.magicapi.iot.bus;
import com.fasterxml.jackson.databind.ObjectMapper; import org.apache.pulsar.client.api.PulsarClient; import org.springframework.boot.autoconfigure.AutoConfiguration; import org.springframework.boot.autoconfigure.condition.*; import org.springframework.context.annotation.Bean; import org.ssssssss.magicapi.iot.core.spi.DeviceMessageBus;
@AutoConfiguration @ConditionalOnProperty(prefix="iot.providers.message-bus",name="type",havingValue="pulsar") public class PulsarMessageBusAutoConfiguration { @Bean(destroyMethod="close") @ConditionalOnMissingBean PulsarClient pulsarClient(org.springframework.core.env.Environment env)throws Exception{return PulsarClient.builder().serviceUrl(env.getProperty("iot.providers.message-bus.service-url","pulsar://127.0.0.1:6650")).build();} @Bean(destroyMethod="close") @ConditionalOnMissingBean(DeviceMessageBus.class) DeviceMessageBus deviceMessageBus(PulsarClient client,ObjectMapper mapper,org.springframework.core.env.Environment env)throws Exception{return new PulsarDeviceMessageBus(client,mapper,env.getProperty("iot.providers.message-bus.topic","iot-device-messages"),env.getProperty("iot.providers.message-bus.retries",Integer.class,3),env.getProperty("iot.providers.message-bus.retry-delay-ms",Long.class,1000L),env.getProperty("iot.providers.message-bus.max-pending",Integer.class,1000));} }
